from flask import Blueprint, request
from app.models import Product
from app.utils.validators import validate_product_data
from app.utils.responses import success_response, error_response
from app.database import db

bp = Blueprint('products', __name__, url_prefix='/api/products')

# Constants
PRODUCT_NOT_FOUND = 'Producto no encontrado'

@bp.route('', methods=['GET'])
def get_products():
    """Obtiene todos los productos con filtros opcionales"""
    # Obtener filtros de query params
    filters = {
        'min_price': request.args.get('min_price', type=float),
        'max_price': request.args.get('max_price', type=float),
        'category': request.args.get('category')
    }

    products = Product.get_all(filters=filters)

    return success_response(
        data=[product.to_dict() for product in products],
        count=len(products)
    )

@bp.route('/<int:product_id>', methods=['GET'])
def get_product(product_id):
    """Obtiene un producto específico por ID"""
    product = Product.get_by_id(product_id)

    if not product:
        return error_response(PRODUCT_NOT_FOUND, 404)

    return success_response(data=product.to_dict())

@bp.route('', methods=['POST'])
def create_product():
    """Crea un nuevo producto"""
    data = request.get_json()

    # Validar datos
    is_valid, error_message = validate_product_data(data)
    if not is_valid:
        return error_response(error_message, 400)

    try:
        # Crear y guardar producto
        product = Product(
            name=data['name'],
            price=data['price'],
            category_id=data['category_id'],
            description=data.get('description', ''),
            stock=data.get('stock', 0),
            cost=data.get('cost', 0)
        )
        product.save()

        return success_response(
            data=product.to_dict(),
            message='Producto creado exitosamente',
            status_code=201
        )
    except Exception as e:
        db.session.rollback()
        return error_response(f'Error al crear producto: {str(e)}', 500)

@bp.route('/<int:product_id>', methods=['PUT'])
def update_product(product_id):
    """Actualiza un producto existente"""
    product = Product.get_by_id(product_id)

    if not product:
        return error_response(PRODUCT_NOT_FOUND, 404)

    data = request.get_json()

    if not data:
        return error_response('No se proporcionaron datos para actualizar', 400)

    try:
        # Actualizar producto
        product.update(**data)

        return success_response(
            data=product.to_dict(),
            message='Producto actualizado exitosamente'
        )
    except Exception as e:
        db.session.rollback()
        return error_response(f'Error al actualizar producto: {str(e)}', 500)

@bp.route('/<int:product_id>', methods=['DELETE'])
def delete_product(product_id):
    """Elimina un producto"""
    product = Product.get_by_id(product_id)

    if not product:
        return error_response(PRODUCT_NOT_FOUND, 404)

    try:
        product_data = product.to_dict()
        product.delete()

        return success_response(
            data=product_data,
            message='Producto eliminado exitosamente'
        )
    except Exception as e:
        db.session.rollback()
        return error_response(f'Error al eliminar producto: {str(e)}', 500)

@bp.route('/low-stock', methods=['GET'])
def get_low_stock_products():
    """Obtiene productos con stock bajo o igual al umbral

    Query: Product.query.filter(Product.stock <= threshold).order_by(Product.stock.asc()).all()
    Default threshold=10 si omitido; rechazar negativo/no entero ANTES del query.
    restock_value = float(cost) * (threshold - stock)
    Dict id/name/sku/stock/restock_value.
    """
    threshold_arg = request.args.get('threshold')
    if threshold_arg is None:
        threshold = 10
    else:
        try:
            threshold = int(threshold_arg)
        except (TypeError, ValueError):
            return error_response('El umbral debe ser un número entero', 400)
        if threshold < 0:
            return error_response('El umbral debe ser un número entero no negativo', 400)

    products = Product.query.filter(Product.stock <= threshold).order_by(Product.stock.asc()).all()

    result = [
        {
            'id': p.id,
            'name': p.name,
            'sku': p.sku,
            'stock': p.stock,
            'restock_value': float(p.cost) * (threshold - p.stock) if p.cost is not None else 0.0
        }
        for p in products
    ]

    return success_response(
        data=result,
        count=len(result)
    )

from sqlalchemy import func
from app.database import db
from app.models import Product, Category


class InventoryAnalytics:
    """Clase para análisis de inventario"""

    @staticmethod
    def get_low_stock_products(threshold=10):
        """Obtiene productos con stock bajo"""
        products = Product.query.filter(Product.stock <= threshold).all()

        return [
            {
                'id': p.id,
                'name': p.name,
                'stock': p.stock,
                'category': p.category.name if p.category else None,
                'price': float(p.price)
            }
            for p in products
        ]

    @staticmethod
    def get_out_of_stock_products():
        """Obtiene productos sin stock"""
        products = Product.query.filter(Product.stock == 0).all()

        return [
            {
                'id': p.id,
                'name': p.name,
                'category': p.category.name if p.category else None,
                'price': float(p.price)
            }
            for p in products
        ]

    @staticmethod
    def get_inventory_value():
        """Calcula el valor total del inventario"""
        result = db.session.query(
            func.sum(Product.price * Product.stock)
        ).scalar()

        return float(result) if result else 0.0

    @staticmethod
    def get_inventory_by_category():
        """Obtiene inventario agrupado por categoría"""
        results = db.session.query(
            Category.id,
            Category.name,
            func.count(Product.id).label('product_count'),
            func.sum(Product.stock).label('total_stock'),
            func.sum(Product.price * Product.stock).label('total_value')
        ).join(
            Product, Category.id == Product.category_id
        ).group_by(
            Category.id, Category.name
        ).all()

        return [
            {
                'category_id': r.id,
                'category_name': r.name,
                'product_count': r.product_count,
                'total_stock': r.total_stock or 0,
                'total_value': float(r.total_value) if r.total_value else 0.0
            }
            for r in results
        ]

    @staticmethod
    def get_inventory_summary():
        """Obtiene un resumen del inventario"""
        total_products = db.session.query(func.count(Product.id)).scalar()
        total_stock = db.session.query(func.sum(Product.stock)).scalar()
        total_value = InventoryAnalytics.get_inventory_value()
        low_stock_count = db.session.query(func.count(Product.id)).filter(
            Product.stock <= 10
        ).scalar()
        out_of_stock_count = db.session.query(func.count(Product.id)).filter(
            Product.stock == 0
        ).scalar()

        return {
            'total_products': total_products or 0,
            'total_stock': total_stock or 0,
            'total_value': total_value,
            'low_stock_count': low_stock_count or 0,
            'out_of_stock_count': out_of_stock_count or 0
        }

